<?php require_once __DIR__.'/../config/auth.php'; require_once __DIR__.'/../config/database.php'; if($_SERVER['REQUEST_METHOD']!=='POST'||!verify_csrf($_POST['_csrf']??null)){flash('error','Invalid request.');redirect('auth/login.php');} $email=trim((string)($_POST['email']??''));$pass=(string)($_POST['password']??'');$st=db()->prepare('SELECT id,password_hash,status FROM users WHERE email=? LIMIT 1');$st->execute([$email]);$u=$st->fetch();if(!$u||($u['status']??'active')!=='active'||!password_verify($pass,$u['password_hash']??'')){flash('error','Invalid credentials.');redirect('auth/login.php');}session_regenerate_id(true);$_SESSION['user_id']=(int)$u['id'];redirect('dashboard/index.php');
